export const MOCK_DATE = '2026-05-14';

/** Single studio centre shared by all mock appointments. */
export const MOCK_CENTRO_ID = 1;
export const MOCK_CENTRO_NAME = 'Centro Suksai';

/**
 * Stamps the shared mock centro (id + name) onto each appointment so fixtures
 * satisfy IAgendaAppointment's required centro fields without repeating them on
 * every literal.
 */
const withMockCentro = (
  appts: readonly Omit<IAgendaAppointment, 'centroId' | 'centroName'>[],
): IAgendaAppointment[] =>
  appts.map((a) => ({ ...a, centroId: MOCK_CENTRO_ID, centroName: MOCK_CENTRO_NAME }));

